# Run from PowerShell (in project root):
# julia --project=. .\test_goldilocks_deficit_debt.jl
# No GitHub Actions or new project directories required.

using Test
using LinearAlgebra

include(joinpath(@__DIR__,"GoldilocksCore.jl"))
include(joinpath(@__DIR__,"GoldilocksHouseholds.jl"))
include(joinpath(@__DIR__,"GoldilocksCalibration.jl"))
include(joinpath(@__DIR__,"GoldilocksDeficitDebt.jl"))

using .GoldilocksCore
using .GoldilocksHouseholds
using .GoldilocksCalibration
using .GoldilocksDeficitDebt

# These are independently generated by executing the original
# auxfs.get_deficit_debt(ss['bu'],model_ss['bu'],8,12,ss_opt=...)
# with unmodified official calibration pickle INPUTS, not digitized figures.
const SOURCE_NONZLB = Dict(
    :us => (
        B=(-0.005782605383049474,0.370425581625866,
           0.7058792597201459,1.0099177162680897,
           1.28913948450964,1.548218922146258,
           1.7904502003141771,2.0181241940066994),
        deficit=(-0.00020012350002121537,0.010982962854206302,
                 0.017429088231655676,0.01992876004424049,
                 0.01904676505600722,0.015198132248351537,
                 0.008698478509079677,-0.00020181241839056785),
        boundary_Y=1.066330327875318),
    :jp => (
        B=(0.5147919263453866,0.978748121038963,
           1.4335610237593586,1.8809258076334403,
           2.3214247783920876,2.754726912609701,
           3.1798174637373915,3.5952562956989174),
        deficit=(0.011638335119141863,0.018952347019412674,
                 0.023108843080611285,0.02421863210069658,
                 0.0223598074044416,0.017597072056600827,
                 0.009997274849576077,-0.000359525627770807),
        boundary_Y=1.1523931314235947),
)

@testset "GoldilocksDeficitDebt: source model, stationary GE, and Figure 8" begin
    @testset "Source Figure 8 country/model/frequency and grids" begin
        @test FIGURE8_MODELS == (:bu,:bu_log,:olg,:ha)
        @test !(:olg_alt in FIGURE8_MODELS)
        for country in (:us,:jp)
            s=country_setup(country,1)
            @test s.periods==1
            @test_throws ArgumentError figure8_calibration(country,:olg_alt;mode=:official)
            @test_throws ArgumentError figure8_calibration(country,:bu;mode=:something)
            @test_throws ArgumentError original_debt_grids(0.02,0.015,1.0;n_r=1,n_Y=10)
            @test_throws DomainError original_debt_grids(0.02,0.015,0.0)
            g=original_debt_grids(s.core.monetary.pi_trend,
                                  s.core.monetary.real_growth,1.2)
            @test length(g.r_grid)==40
            @test length(g.Y_grid)==70
            @test g.Y_grid[1]==0
            @test g.Y_grid[end]==1.2
            @test g.r_grid[end]==1e-4
            @test all(diff(g.r_grid).>0)
            @test all(diff(g.Y_grid).>0)
            @test g.r_zlb≈(1/(1+s.core.monetary.pi_trend)-1-s.core.monetary.real_growth)
        end
    end

    @testset "Official parameters are inputs, never stored curve output" begin
        s=country_setup(:us,1)
        @test official_household(s,:bu) isa BUQuadratic
        @test official_household(s,:bu_log) isa BULog
        @test official_household(s,:olg) isa OLGHousehold
        @test official_household(s,:ha) isa HAHousehold
        @test official_household(s,:bu).vp_slope≈0.2862183664715453
        @test official_household(s,:ha).eis≈0.21904952574407402
        @test_throws ArgumentError official_household(country_setup(:jp,4),:bu)
        @test_throws ArgumentError official_household(s,:olg_alt)
    end

    @testset "Native HA Figure 8 calibration uses the validated Task V method" begin
        # The task-V test suite calibrates HA with :implicit, then verifies
        # the ORIGINAL finite-difference GE elasticity independently. The
        # previous figure driver defaulted to :finite also for HA and could
        # fail in a noisy scalar-Newton line search before solving any curve.
        for country in (:us,:jp)
            input = figure8_calibration(country,:ha;mode=:native)
            @test input.household isa HAHousehold
            @test input.source !== nothing
            @test input.mode === :native
            # The IFT calibration target and the independently re-solved
            # source-style finite-difference GE moment are separate checks.
            # With h = -1e-5, baseline asset-market error is strongly
            # amplified in Δlog(B), so verify inner clearing FIRST.
            @test abs(input.anchor.asset_mkt) < 1e-7
            @test abs(input.source.phi_error) < 5e-5
            @test abs(input.source.phi_finite_error) < 5e-5
            @test abs(input.anchor.goods_mkt) < 5e-5
        end
        @test_throws ArgumentError figure8_calibration(:us,:bu;
                                                       mode=:native,method=:invalid)
    end

    @testset "Original Python Figure 8 non-ZLB parity: 2 countries, 8 grid points" begin
        for country in (:us,:jp)
            input=figure8_calibration(country,:bu;mode=:official)
            ss=input.setup.state
            @test ss.Y≈1
            @test ss.B≈(country==:us ? 1.0 : 2.38)
            b=zlb_boundary(input.core,input.household,ss)
            ref=SOURCE_NONZLB[country]
            @test isapprox(b.Y,ref.boundary_Y;atol=3e-3)
            @test isapprox(b.B,ref.B[1];atol=3e-3)
            @test abs(b.eq.asset_mkt)<1e-5
            @test abs(b.eq.labor_foc)<1e-5
            @test abs(b.eq.i)<1e-5
            # A reduced grid is used for inexpensive regression testing;
            # publication code still uses the original 40 x 70 grids.
            curve=deficit_debt_curve(input.setup,input.household,input.core;
                                      model=:bu,mode=:official,n_r=8,n_Y=12,
                                      root_tol=1e-7,tol=2e-5)
            @test length(curve.records)==20
            @test length(curve.r_grid)==8
            @test length(curve.Y_grid)==12
            @test isapprox(curve.boundary.Y,ref.boundary_Y;atol=3e-3)
            for k in 1:8
                pt=curve.records[12+k]
                @test !ismissing(pt)
                if !ismissing(pt)
                    @test pt.branch===:flex
                    @test isapprox(pt.B,ref.B[k];atol=3e-3)
                    @test isapprox(pt.deficit,ref.deficit[k];atol=2e-4)
                    @test pt.residual<2e-5
                    @test abs(pt.deficit+pt.r_ante*pt.B)<2e-5
                    @test pt.i>=-2e-5
                end
            end
            @test any(p->!ismissing(p)&&p.branch===:zlb,curve.records)
            @test all(p->ismissing(p)||p.residual<2e-5,curve.records)
            mx=grid_maximum(curve)
            @test mx.maximum_deficit>0
            @test mx.debt_at_maximum>0
            @test mx.count>=8
            # A wrong regime or large residual is never silently accepted.
            probe=curve.records[end]
            @test !ismissing(probe)
            if !ismissing(probe)
                @test probe.i>=-2e-5
            end
            # Source writes every attempted/unattempted slot, not just successes.
            path=write_curve_data(curve;directory=@__DIR__)
            @test isfile(path)
            @test length(readlines(path))==21
            @test occursin("UNSOLVED",read(path,String))
            rm(path;force=true)
            table_path=make_deficit_debt_table([curve];directory=@__DIR__,
                                     filename="_figure8_test_maxima.tex").path
            @test isfile(table_path)
            @test filesize(table_path)>100
            rm(table_path;force=true)
        end
    end

    @testset "Debt-accounting and economic validation" begin
        input=figure8_calibration(:us,:bu;mode=:official)
        baseline=input.anchor
        @test isapprox(baseline.asset_mkt,0;atol=1e-5)
        @test isapprox(baseline.goods_mkt,0;atol=1e-5)
        diagnostic=validate_point(baseline,input.core;tol=2e-5)
        @test diagnostic.residual<2e-5
        @test isapprox(baseline.deficit,-baseline.rpost_bonds*baseline.B;atol=1e-8)
        # Fixed B should also solve an endogenous general equilibrium, not
        # evaluate a partial-equilibrium asset demand.
        solved=solve_fixed_debt(input.core,input.household,1.0;
                                guess=(;r_ante=input.setup.state.r_ante,Y=1.0,piw=0.0))
        @test abs(solved.asset_mkt)<2e-5
        @test abs(solved.labor_foc)<2e-5
        @test isapprox(solved.Y,1.0;atol=2e-3)
        # Exercise the distinct 3-dimensional ZLB closure, too.  At the
        # regime boundary the source's non-ZLB and ZLB equations coincide.
        boundary=zlb_boundary(input.core,input.household,input.setup.state)
        binding_solved=solve_fixed_debt(input.core,input.household,boundary.B;
                              binding=true,
                              guess=(;r_ante=boundary.r_ante,Y=boundary.Y,piw=0.0))
        @test abs(binding_solved.asset_mkt)<2e-5
        @test abs(binding_solved.fisher)<2e-5
        @test abs(binding_solved.piw_cond)<2e-5
        @test isapprox(binding_solved.Y,boundary.Y;atol=2e-3)
        @test_throws ArgumentError solve_fixed_debt(input.core,input.household,1.0)
    end

    @testset "Native vs official: only common grid arguments comparable" begin
        input=figure8_calibration(:us,:bu;mode=:official)
        a=deficit_debt_curve(input.setup,input.household,input.core;
                             model=:bu,mode=:official,n_r=8,n_Y=12)
        # Identical inputs must imply zero exact-grid differences.
        cmp=compare_curves(a,a)
        @test length(cmp)==20
        @test all(r->!r.matched||abs(r.debt_gap)<1e-14,cmp)
        @test all(r->!r.matched||abs(r.deficit_gap)<1e-14,cmp)
        b=DeficitDebtCurve(:jp,a.periods,a.model,a.mode,
                           a.setup,a.household,a.core,a.r_grid,a.Y_grid,
                           a.records,a.issues,a.boundary)
        @test_throws ArgumentError compare_curves(a,b)
        # ZLB indices with different Y grids must never be compared naively.
        changed=copy(a.Y_grid)
        changed[2] *= 1.01
        c=DeficitDebtCurve(a.country,a.periods,a.model,a.mode,
                           a.setup,a.household,a.core,a.r_grid,changed,
                           a.records,a.issues,a.boundary)
        comparison=compare_curves(a,c)
        @test !comparison[2].matched
        @test ismissing(comparison[2].debt_gap)
    end
end

println("GoldilocksDeficitDebt tests finished; check source parity in Test Summary.")
